                        + " GROUP BY c.id, c.name"
                        + " ORDER BY outstanding DESC, c.id ASC"
                        + " LIMIT ?",
                (rs, n) -> new TopClient(
                        rs.getLong("client_id"), rs.getString("name"),
                        rs.getBigDecimal("outstanding")),
                limit);
    }
